using System.Numerics;
using System.Runtime.InteropServices;

namespace CatalogSvc;

public class ProductCatalog
{
    private readonly Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, double> _prices = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, List<string>> _categoryIndex = new(StringComparer.OrdinalIgnoreCase);

    public void AddProduct(string code, string category, double price)
    {
        // Remove from old category index if updating
        if (_categories.TryGetValue(code, out var oldCategory))
        {
            if (_categoryIndex.TryGetValue(oldCategory, out var oldList))
                oldList.Remove(code);
        }

        _categories[code] = category;
        _prices[code] = price;

        ref var list = ref CollectionsMarshal.GetValueRefOrAddDefault(_categoryIndex, category, out bool exists);
        if (!exists)
            list = new List<string>();
        list!.Add(code);
    }

    public string? GetCategory(string code)
        => _categories.TryGetValue(code, out var cat) ? cat : null;

    /// <summary>
    /// Sums prices for the given codes using SIMD-vectorized addition.
    /// </summary>
    public double GetTotalPrice(IEnumerable<string> codes)
    {
        // Resolve prices into a contiguous buffer for vectorized summation
        Span<double> buffer = stackalloc double[128];
        int count = 0;
        double[]? rentedArray = null;

        foreach (var code in codes)
        {
            if (_prices.TryGetValue(code, out var price))
            {
                if (count == buffer.Length)
                {
                    // Spill to heap when exceeding stack buffer
                    var newArray = new double[buffer.Length * 2];
                    buffer.CopyTo(newArray);
                    rentedArray = newArray;
                    buffer = rentedArray;
                }
                else if (rentedArray != null && count == rentedArray.Length)
                {
                    var newArray = new double[rentedArray.Length * 2];
                    rentedArray.CopyTo(newArray.AsSpan());
                    rentedArray = newArray;
                    buffer = rentedArray;
                }
                buffer[count++] = price;
            }
        }

        return SimdSum(buffer[..count]);
    }

    /// <summary>
    /// Returns products in the given category via a reverse index (O(1) lookup).
    /// </summary>
    public List<string> GetProductsByCategory(string category)
    {
        if (_categoryIndex.TryGetValue(category, out var list))
            return new List<string>(list);
        return new List<string>();
    }

    private static double SimdSum(ReadOnlySpan<double> values)
    {
        if (values.IsEmpty)
            return 0.0;

        int vectorSize = Vector<double>.Count;
        var vectors = MemoryMarshal.Cast<double, Vector<double>>(values);
        var accumulator = Vector<double>.Zero;

        for (int i = 0; i < vectors.Length; i++)
            accumulator += vectors[i];

        double result = Vector.Sum(accumulator);

        // Handle remaining elements beyond the last full vector
        int processed = vectors.Length * vectorSize;
        for (int i = processed; i < values.Length; i++)
            result += values[i];

        return result;
    }
}

